extends Node

# Source IDs matching the tilesets/dungeon.tres resource structure:
const FLOOR_ID := 0
const WALL_ID := 1
# const DOOR_ID := 2

@export var seed: int = 12345
@export var width: int = 64
@export var height: int = 64
@export var wall_threshold: float = 0.0

var _rooms: Array[Rect2i] = []

# Deterministic RNG
var _rng := RandomNumberGenerator.new()

func _seed_everything() -> void:
    # Set the RNG seed directly (do not pass the RNG object as an argument)
    _rng.seed = seed
    print_debug("_rng.seed set to ", _rng.seed)

func _rng_range(from: int, to: int) -> int:
    return _rng.randi_range(from, to)

func _rng_int(to: int) -> int:
    # Use randi_range for a bounded range [0, to - 1]
    return _rng.randi_range(0, to - 1)

func _rng_float() -> float:
    return _rng.randf()

func _rng_bool() -> bool:
    return _rng.randf() < 0.5

func generate(target: TileMapLayer) -> void:
    print_debug("DungeonGenerator.generate(seed=", seed, ")")
    _rooms.clear()
    _seed_everything()

    target.clear()

    # Noise pass
    var noise := FastNoiseLite.new()
    noise.seed = seed
    print_debug("FastNoiseLite.seed set to ", noise.seed)
    # Use Cellular noise for cavernous look; keep defaults for other params
    noise.noise_type = FastNoiseLite.TYPE_CELLULAR

    for y in range(height):
        for x in range(width):
            var value := noise.get_noise_2d(x, y)
            var source_id := FLOOR_ID
            if value > wall_threshold:
                source_id = WALL_ID
            target.set_cell(Vector2i(x, y), source_id, Vector2i(0, 0))

    # Edge cells must be walls regardless of noise
    for x in range(width):
        target.set_cell(Vector2i(x, 0), WALL_ID, Vector2i(0, 0))
        target.set_cell(Vector2i(x, height - 1), WALL_ID, Vector2i(0, 0))
    for y in range(height):
        target.set_cell(Vector2i(0, y), WALL_ID, Vector2i(0, 0))
        target.set_cell(Vector2i(width - 1, y), WALL_ID, Vector2i(0, 0))

    _carve_rooms(target)
    _carve_corridors(target)

func count_floor_tiles(target: TileMapLayer) -> int:
    var count: int = 0
    for y in range(height):
        for x in range(width):
            if target.get_cell_source_id(Vector2i(x, y)) == FLOOR_ID:
                count += 1
    return count

func find_rooms() -> Array[Rect2i]:
    # Return a shallow copy so callers don't mutate the generator's state
    var copy: Array[Rect2i] = []
    copy.assign(_rooms)
    return copy

# --- Room carving ---

func _carve_rooms(target: TileMapLayer) -> void:
    var num_attempts: int = 100
    var min_room_size: int = 3
    var max_room_size: int = 10

    for i in range(num_attempts):
        var w: int = _rng_range(min_room_size, max_room_size)
        var h: int = _rng_range(min_room_size, max_room_size)

        # Rooms must be contained strictly within the interior [1, width-2]
        # so the room rectangle [x, x+w) must satisfy:
        #   x >= 1
        #   x + w <= width - 1
        var max_x: int = width - 1 - w
        var max_y: int = height - 1 - h

        if max_x < 1 or max_y < 1:
            continue

        var x: int = _rng_range(1, max_x)
        var y: int = _rng_range(1, max_y)
        var room := Rect2i(x, y, w, h)

        if _is_overlapping(room):
            continue
        _rooms.append(room)
        _fill_rect(target, room, FLOOR_ID)

func _is_overlapping(room: Rect2i) -> bool:
    for other in _rooms:
        if room.intersects(other):
            return true
    return false

# --- Corridor carving (straight L-shaped connecting rooms) ---

func _carve_corridors(target: TileMapLayer) -> void:
    if _rooms.size() < 2:
        return
    for i in range(_rooms.size() - 1):
        _connect(_rooms[i], _rooms[i + 1], target)

func _connect(a: Rect2i, b: Rect2i, target: TileMapLayer) -> void:
    var center_a := _center(a)
    var center_b := _center(b)

    # Pick a random corner for the L-bend: either (ax, by) or (bx, ay)
    var corner: Vector2i
    if _rng_bool():
        corner = Vector2i(center_a.x, center_b.y)
    else:
        corner = Vector2i(center_b.x, center_a.y)

    _draw_line(target, center_a, corner)
    _draw_line(target, corner, center_b)

func _center(r: Rect2i) -> Vector2i:
    return Vector2i(r.position.x + r.size.x / 2, r.position.y + r.size.y / 2)

# Draw a straight line between two points. Assumes either horizontal or vertical.
func _draw_line(target: TileMapLayer, from: Vector2i, to: Vector2i) -> void:
    if from.x == to.x:
        var start_y: int = min(from.y, to.y)
        var end_y: int = max(from.y, to.y)
        for y in range(start_y, end_y + 1):
            target.set_cell(Vector2i(from.x, y), FLOOR_ID, Vector2i(0, 0))
    else:
        var start_x: int = min(from.x, to.x)
        var end_x: int = max(from.x, to.x)
        for x in range(start_x, end_x + 1):
            target.set_cell(Vector2i(x, from.y), FLOOR_ID, Vector2i(0, 0))

func _fill_rect(target: TileMapLayer, r: Rect2i, source_id: int) -> void:
    for y in range(r.position.y, r.end.y):
        for x in range(r.position.x, r.end.x):
            target.set_cell(Vector2i(x, y), source_id, Vector2i(0, 0))

